package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.JsonSerializable;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.annotation.JsonSerialize;
import com.fasterxml.jackson.databind.util.RawValue;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.verify;

@RunWith(MockitoJUnitRunner.class)
public class POJONode_serialize_TriageGen1Test {

    @Mock
    private JsonGenerator gen;

    @Mock
    private SerializerProvider ctxt;

    /**
     * Mock interface to simulate JsonSerializable behavior
     */
    interface JsonSerializable {
        void serialize(JsonGenerator gen, SerializerProvider ctxt) throws IOException;
    }

    /**
     * Mock class to implement JsonSerializable
     */
    static class MockSerializable implements JsonSerializable {
        @Override
        public void serialize(JsonGenerator gen, SerializerProvider ctxt) throws IOException {
            gen.writeString("serialized");
        }
    }

    @Test
    public void testSerialize_withNullValue() throws IOException {
        // Arrange
        POJONode node = new POJONode(null);

        // Act
        node.serialize(gen, ctxt);

        // Assert
        verify(ctxt).defaultSerializeNull(gen);
    }

    @Test
    public void testSerialize_withJsonSerializableValue() throws IOException {
        // Arrange
        MockSerializable serializable = new MockSerializable();
        POJONode node = new POJONode(serializable);

        // Act
        node.serialize(gen, ctxt);

        // Assert
        verify(gen).writeString("serialized");
    }

    @Test
    public void testSerialize_withStandardPojo() throws IOException {
        // Arrange
        String value = "test-string";
        POJONode node = new POJONode(value);

        // Act
        node.serialize(gen, ctxt);

        // Assert
        verify(gen).writeObject(value);
    }

    @Test(expected = IOException.class)
    public void testSerialize_withStandardPojo_throwsException() throws IOException {
        // Arrange
        Object value = new Object();
        POJONode node = new POJONode(value);
        doThrow(new IOException("Simulated error")).when(gen).writeObject(value);

        // Act
        node.serialize(gen, ctxt);
    }

    @Test
    public void testSerialize_withJsonSerializable_throwsException() throws IOException {
        // Arrange
        JsonSerializable serializable = (gen, ctxt) -> {
            throw new IOException("Serializable error");
        };
        POJONode node = new POJONode(serializable);

        // Act & Assert
        try {
            node.serialize(gen, ctxt);
        } catch (IOException e) {
            // Expected
        }
    }

    @Test(expected = IOException.class)
    public void testSerialize_withNullValue_throwsException() throws IOException {
        // Arrange
        POJONode node = new POJONode(null);
        doThrow(new IOException("Null error")).when(ctxt).defaultSerializeNull(gen);

        // Act
        node.serialize(gen, ctxt);
    }
}
